import { copyFile, mkdir, readFile, stat, writeFile } from "node:fs/promises";
import { basename, extname, join } from "node:path";
import { randomUUID } from "node:crypto";
import { z } from "zod";
import { AuditEvent, BlockId, ConnectionReport, PipelineData, ResearchDataset, ResearchLimits, ResearchProviderConfig, ResearchProviderId, SECRET_NAMES, SecretName, Settings, Workflow, WorkflowRun, validateGraph, walkBlocks, type AuditEventInput, type ResearchProviderStatus } from "@reqflow/core";
import type { AuditFilter, ReqflowHandlers, StoredFileInfo } from "@reqflow/core/ipc";
import { BlockRegistry, executeWorkflow, type BlockContext } from "@reqflow/engine";
import { allBlockImplementations, RESEARCH_AGENTS, PROVIDER_SECRETS, createLocalDocumentReader, createProviderHttp, createResearchAdapters, createResearchCollector, exportResearchCsv, exportResearchJson, exportResearchXlsx, mergeResearchDatasets, ProviderError, redactSecrets } from "@reqflow/blocks";
import { ReqflowError } from "../dispatch";
import { SecretStore, type SecureStorage } from "./secrets";
import { ResearchStore, validRun } from "./storage";

type ResearchHandlers=Pick<ReqflowHandlers,"settings"|"workflows"|"runs"|"research"|"files"|"audit">&{exports:Pick<ReqflowHandlers["exports"],"research">};
export interface RuntimeDeps {
  dir:string;secureStorage:SecureStorage;platform?:NodeJS.Platform;
  chooseImport():Promise<string|null>;
  chooseExport(format:"json"|"xlsx"|"csv",runId:string):Promise<string|null>;
  publish(run:WorkflowRun):void;
  fetchImpl?:typeof fetch;
  xlsxWorkerPath?:string;
}
const FileInfo=z.object({id:z.string().regex(/^file_[A-Za-z0-9_-]+$/),name:z.string(),mimeType:z.string(),sizeBytes:z.number().nonnegative(),importedAt:z.iso.datetime(),extension:z.enum([".xlsx",".txt",".pdf",".docx",".pptx"])});
const FILE_TYPES:Record<string,string>={".xlsx":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",".txt":"text/plain",".pdf":"application/pdf",".docx":"application/vnd.openxmlformats-officedocument.wordprocessingml.document",".pptx":"application/vnd.openxmlformats-officedocument.presentationml.presentation"};
export async function createResearchRuntime(deps:RuntimeDeps):Promise<{handlers:ResearchHandlers;shutdown():Promise<void>}> {
  const store=new ResearchStore(deps.dir);const secrets=new SecretStore(deps.dir,deps.secureStorage,deps.platform);
  await store.load();await secrets.load();
  const registry=new BlockRegistry();for(const implementation of allBlockImplementations)registry.register(implementation);
  const adapters=createResearchAdapters();
  const reports=new Map<ResearchProviderId,ConnectionReport>();
  const versions=new Map<ResearchProviderId,number>();
  const jobs=new Map<string,{controller:AbortController;promise:Promise<unknown>;outputs:Record<string,Record<string,PipelineData>>}>();
  const tests=new Map<ResearchProviderId,Promise<ResearchProviderStatus>>();
  const startingWorkflows=new Set<string>();
  const launchingRuns=new Set<string>();
  const resumingRuns=new Set<string>();
  const fileQueue={promise:Promise.resolve() as Promise<unknown>};
  const clone=<T>(value:T):T=>structuredClone(value);
  const actor=()=>({type:"human" as const,...store.state.settings.review.reviewer});
  const credentials=()=>Object.fromEntries(SECRET_NAMES.map((name)=>[name,secrets.get(name)]));
  const configured=(id:ResearchProviderId)=>{
    const status=secrets.status();return Object.fromEntries(PROVIDER_SECRETS[id].map((name)=>[name,status[name].configured]));
  };
  function status(id:ResearchProviderId):ResearchProviderStatus {
    const flags=configured(id);const required=id==="openalex"?[]:PROVIDER_SECRETS[id];
    return {id,config:clone(store.state.settings.research.apis[id]),credentialsConfigured:flags,
      connection:reports.get(id)??{state:required.some((key)=>!flags[key])?"not_configured":"untested",message:required.some((key)=>!flags[key])?"Required credentials are missing.":"Configured but not tested. No provider request has been made.",capabilities:[],limitations:[]}};
  }
  function invalidate(id:ResearchProviderId):void {versions.set(id,(versions.get(id)??0)+1);reports.delete(id);}
  const audit=async(input:AuditEventInput)=>{
    const event=AuditEvent.parse({...input,id:`aud_${randomUUID()}`,at:new Date().toISOString(),changes:input.changes??[]});
    await store.audit(event);return event;
  };
  const resolveFile=async(id:string)=>{
    FileInfo.shape.id.parse(id);
    const list=await store.read("files.json",z.array(FileInfo));const entry=list.find((file)=>file.id===id);
