      try {
        await executeWorkflow({run:input,registry,outputs,
          context:(blockId):BlockContext=>({runId:input.id,blockId,scope:input.scope,settings:snapshot,signal:controller.signal,resumed:false,
            llm:{generateObject:async()=>{throw new ReqflowError("not_implemented","Analytical LLM blocks are owned by their workstreams; raw Research does not analyze source content.");},generateText:async()=>{throw new ReqflowError("not_implemented","LLM text generation is not configured for this block.");}},
            audit:{record:audit},files:{get:async(id)=>{const file=await resolveFile(id);return {id,name:file.name,mimeType:file.entry.mimeType,bytes:new Uint8Array(await readFile(file.path))};}},web:null,
            car:{add:async()=>{throw new ReqflowError("not_implemented","Requirements persistence is not configured in the Research runtime.");}},log:()=>{},progress:()=>{},
