            }},
          }),
          onUpdate:async(value)=>{
            if(!["running","queued"].includes(value.status))await Promise.allSettled([...pending]);
            const run=clone(value);
            for(const block of run.blockRuns){if(block.error)block.error=safe(block.error);for(const log of block.logs)log.message=safe(log.message);}
            if(run.error)run.error=safe(run.error);
