    const initial=clone(input);
    const promise=Promise.resolve().then(execute);jobs.set(input.id,{controller,promise,outputs});
    return initial;
    } catch(error) {
      const run=getRun(input.id);run.status="failed";run.error="Research runtime could not be initialized. Check secure storage and local data availability.";run.finishedAt=new Date().toISOString();await store.saveState();publish(run);throw error;
    } finally {launchingRuns.delete(input.id);}
  }
  const handlers:ResearchHandlers={
    settings:{get:async()=>clone(store.state.settings),secrets:async()=>secrets.status(),
      save:async(input)=>{
        const settings=Settings.parse(input);
        // Dedicated configure owns provider access flags; stale general-settings autosaves must
        // not re-enable providers or undo an explicit approval/revocation.
