        await audit({actor:actor(),action:"settings.changed",entityType:"settings",entityId:"app",rationale:"General app settings saved; no credential values in audit."});return clone(settings);
      },
      setSecret:async(name,value)=>{const key=SecretName.parse(name);const result=await secrets.set(key,value);for(const id of ResearchProviderId.options)if(PROVIDER_SECRETS[id].includes(key))invalidate(id);await audit({actor:actor(),action:"settings.changed",entityType:"settings",entityId:`credential:${key}`,rationale:value===null?"Credential removed.":"Credential stored using OS-backed encryption."});return result;},
    },
    workflows:{list:async()=>clone(store.state.workflows),get:async(id)=>{z.string().startsWith("wf_").parse(id);const wf=store.state.workflows.find((w)=>w.id===id);if(!wf)throw new ReqflowError("not_found","Workflow not found.");return clone(wf);},
      save:async(input)=>{
        const now=new Date().toISOString();const previous=input.id?store.state.workflows.find((w)=>w.id===input.id):undefined;
