      },remove:async(id)=>{z.string().startsWith("wf_").parse(id);store.state.workflows=store.state.workflows.filter((w)=>w.id!==id);await store.saveState();},
    },
    runs:{start:async(workflowId)=>{
      z.string().startsWith("wf_").parse(workflowId);const workflow=store.state.workflows.find((w)=>w.id===workflowId);
