    }},
    research:{agents:async()=>clone(RESEARCH_AGENTS),providers:async()=>ResearchProviderId.options.map(status),
      configure:async(input,value)=>{const id=ResearchProviderId.parse(input);const config=ResearchProviderConfig.parse(value);store.state.settings.research.apis[id]=config;invalidate(id);await store.saveState();await audit({actor:actor(),action:"settings.changed",entityType:"settings",entityId:`provider:${id}`,rationale:"Provider enablement/access configuration saved. No credential values."});return status(id);},
      test:async(input)=>{
        const id=ResearchProviderId.parse(input);const previous=tests.get(id);if(previous)return previous;
        const generation=versions.get(id)??0;const config=clone(store.state.settings.research.apis[id]);
        const promise=(async()=>{
          const flags=configured(id);
          if(id!=="openalex"&&PROVIDER_SECRETS[id].some((name)=>!flags[name]))return status(id);
          const signal=AbortSignal.timeout(15000);const limits=ResearchLimits.parse({maxRequests:3,maxResults:1,maxDocumentPages:1,timeoutMs:15000,retries:0,concurrency:1});
          let report:ConnectionReport;
          try{report=ConnectionReport.parse(await adapters.get(id)!.test({http:createProviderHttp({limits,signal,fetchImpl:deps.fetchImpl}),credentials:credentials(),config,limits,signal,log:()=>{},now:()=>new Date().toISOString(),documents}));}
          catch(error){report={state:error instanceof ProviderError&&["invalid_credentials","permission_required","rate_limited","unsupported"].includes(error.code)?error.code as "invalid_credentials":"unreachable",message:"Provider test failed. No sensitive response details retained.",testedAt:new Date().toISOString(),capabilities:[],limitations:[]};}
          const values=SECRET_NAMES.map((name)=>{try{return secrets.get(name);}catch{return undefined;}}).filter((key):key is string=>!!key);
          report.message=redactSecrets(report.message,values);report.limitations=report.limitations.map((m)=>redactSecrets(m,values));
          if((versions.get(id)??0)===generation)reports.set(id,report);
          return status(id);
        })();tests.set(id,promise);try{return await promise;}finally{tests.delete(id);}
      },dataset:async(id)=>{getRun(id);return store.dataset(id);},
    },
    exports:{research:async(input)=>{
      const {runId,format}=z.strictObject({runId:z.string().regex(/^run_[A-Za-z0-9_-]+$/),format:z.enum(["json","xlsx","csv"])}).parse(input);getRun(runId);
      const dataset=await store.dataset(runId);const path=await deps.chooseExport(format,runId);if(!path)return null;
      await writeFile(path,format==="xlsx"?await exportResearchXlsx(dataset):format==="csv"?exportResearchCsv(dataset):exportResearchJson(dataset),{mode:0o600});
      await audit({actor:actor(),action:"export.created",entityType:"export",entityId:runId,runId,rationale:`Raw research exported as ${format}; no analysis generated.`});return {path};
    }},
    audit:{list:async(input?:AuditFilter)=>{
      const filter=z.object({entityId:z.string().optional(),entityType:AuditEvent.shape.entityType.optional(),actorType:z.enum(["human","ai","system"]).optional(),action:AuditEvent.shape.action.optional(),runId:z.string().startsWith("run_").optional(),limit:z.number().int().min(1).max(1000).default(100)}).strict().parse(input??{});
      let events:AuditEvent[]=[];try{events=await store.read("audit.json",z.array(AuditEvent));}catch(error){if(!(error instanceof ReqflowError)||error.code!=="not_found")throw error;}
      return events.filter((e)=>(!filter.entityId||e.entityId===filter.entityId)&&(!filter.entityType||e.entityType===filter.entityType)&&(!filter.actorType||e.actor.type===filter.actorType)&&(!filter.action||e.action===filter.action)&&(!filter.runId||e.runId===filter.runId)).slice(-filter.limit);
    }},
  };
  return {handlers,async shutdown(){for(const job of jobs.values())job.controller.abort();await Promise.allSettled([...jobs.values()].map((job)=>job.promise));}};
}

