import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { SecretName, SecretStatus } from "@reqflow/core/ipc";

const ENV_VAR_MAP: Record<SecretName, string> = {
  anthropic_api_key: "ANTHROPIC_API_KEY",
  tavily_api_key: "TAVILY_API_KEY",
};

async function getSafeStorage() {
  try {
    const electron = await import("electron");
    return electron.safeStorage;
  } catch {
    return undefined;
  }
}

export class SecretsStore {
  private readonly filePath: string;

  constructor(dataDir: string) {
    this.filePath = join(dataDir, "secrets.json");
  }

  private readAll(): Record<string, string> {
    if (!existsSync(this.filePath)) return {};
    try {
      const content = readFileSync(this.filePath, "utf8");
      return JSON.parse(content) as Record<string, string>;
    } catch {
      return {};
    }
  }

  private writeAll(data: Record<string, string>): void {
    writeFileSync(this.filePath, JSON.stringify(data, null, 2), "utf8");
  }

  async getSecret(name: SecretName): Promise<string | null> {
    const all = this.readAll();
    const stored = all[name];
    if (stored) {
      try {
        const safeStorage = await getSafeStorage();
        if (safeStorage && safeStorage.isEncryptionAvailable()) {
          const buf = Buffer.from(stored, "base64");
          return safeStorage.decryptString(buf);
        }
        return Buffer.from(stored, "base64").toString("utf8");
      } catch {
        // Fallback / corrupted
      }
    }

    const envVar = ENV_VAR_MAP[name];
    if (envVar && process.env[envVar]) {
      return process.env[envVar]!;
    }

    return null;
  }

  async setSecret(name: SecretName, value: string | null): Promise<void> {
    const all = this.readAll();
    if (value === null || value === undefined || value.trim() === "") {
      delete all[name];
    } else {
      const safeStorage = await getSafeStorage();
      if (safeStorage && safeStorage.isEncryptionAvailable()) {
        const encrypted = safeStorage.encryptString(value);
        all[name] = encrypted.toString("base64");
      } else {
        all[name] = Buffer.from(value, "utf8").toString("base64");
      }
    }
    this.writeAll(all);
  }

  async getStatus(): Promise<SecretStatus> {
    const all = this.readAll();
    const result: SecretStatus = {
      anthropic_api_key: { configured: false, source: null },
      tavily_api_key: { configured: false, source: null },
    };

    const keys: SecretName[] = ["anthropic_api_key", "tavily_api_key"];
    for (const key of keys) {
      if (all[key]) {
        result[key] = { configured: true, source: "keychain" };
      } else {
        const envVar = ENV_VAR_MAP[key];
        if (envVar && process.env[envVar]) {
          result[key] = { configured: true, source: "env" };
        } else {
          result[key] = { configured: false, source: null };
        }
      }
    }

    return result;
  }
}

type JsonSchema = Record<string, unknown>;

const FORMATS = new Set([
  "date-time",
  "time",
  "date",
  "duration",
  "email",
  "hostname",
  "uri",
  "ipv4",
  "ipv6",
  "uuid",
]);
const ANNOTATIONS = new Set([
  "type",
  "title",
  "description",
  "enum",
  "const",
  "default",
  "required",
]);
const LOCAL_CONSTRAINTS = new Set([
  "minimum",
  "maximum",
  "exclusiveMinimum",
  "exclusiveMaximum",
  "multipleOf",
  "minLength",
  "maxLength",
  "pattern",
  "maxItems",
  "uniqueItems",
  "minProperties",
  "maxProperties",
  "propertyNames",
]);

/**
 * Transport only the documented Anthropic subset. Original Zod validation remains authoritative.
 * Unsupported scalar/array constraints become descriptions, matching SDK transformation behavior.
 * https://platform.claude.com/docs/en/build-with-claude/structured-outputs#json-schema-limitations
 */
export function anthropicSchema(original: JsonSchema): JsonSchema {
  const output: JsonSchema = {};
  const constraints: string[] = [];
  for (const [key, value] of Object.entries(original)) {
    if (key === "$schema") continue;
    if (
      LOCAL_CONSTRAINTS.has(key) ||
      (key === "minItems" && value !== 0 && value !== 1) ||
      (key === "format" && !FORMATS.has(value as string))
    ) {
      constraints.push(`${key}: ${JSON.stringify(value)}`);
    } else if (ANNOTATIONS.has(key) || key === "format" || key === "minItems") {
      if (
        key === "enum" &&
        (value as unknown[]).some(
          (item) => item !== null && !["string", "number", "boolean"].includes(typeof item),
        )
      ) {
        throw new Error("Anthropic structured outputs do not support complex enum values");
      }
      output[key] = value;
    } else if (key === "properties" || key === "$defs" || key === "definitions") {
      output[key] = Object.fromEntries(
        Object.entries(value as Record<string, JsonSchema>).map(([name, schema]) => [
          name,
          anthropicSchema(schema),
        ]),
      );
    } else if (key === "items") {
      output.items = anthropicSchema(value as JsonSchema);
    } else if (key === "anyOf" || key === "allOf") {
      const alternatives = value as JsonSchema[];
      if (key === "allOf" && alternatives.some((schema) => "$ref" in schema)) {
        throw new Error("Anthropic structured outputs do not support allOf with $ref");
      }
      output[key] = alternatives.map(anthropicSchema);
    } else if (key === "$ref") {
      if (typeof value !== "string" || !value.startsWith("#/")) {
        throw new Error("Anthropic structured outputs do not support external references");
      }
      output.$ref = value;
    } else if (key === "additionalProperties") {
      if (typeof value === "object") {
        throw new Error(
          "Anthropic structured outputs require explicit object properties; schema-valued additionalProperties is unsupported",
        );
      }
      output.additionalProperties = false;
    } else {
      throw new Error(`Unsupported Anthropic schema keyword ${key}`);
    }
  }
  if (
    output.type === "object" ||
    output.properties ||
    (Array.isArray(output.type) && output.type.includes("object"))
  ) {
    output.additionalProperties = false;
  }
  if (constraints.length) {
    output.description = [
      output.description,
      `Local validation constraints: {${constraints.join(", ")}}.`,
    ]
      .filter(Boolean)
      .join(" ");
  }
  return output;
}

